import{_ as n,o as s,c as a,a as t}from"./app-48188b4a.js";const e={},o=t(`<blockquote><p>原文：《手写Promise》（资料库文档，2023-10-11 创建）<br> 定位：面试向的 Promise 原理梳理 + 核心手写实现</p></blockquote><h2 id="一、笔记元信息" tabindex="-1"><a class="header-anchor" href="#一、笔记元信息" aria-hidden="true">#</a> 一、笔记元信息</h2><table><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>日期</td><td>2023-10-11</td></tr><tr><td>categories</td><td>javascript、ecmascript、面试</td></tr><tr><td>tags</td><td>原理、异步</td></tr><tr><td>篇幅</td><td>4 个小节 + 1 段完整代码 + 1 个 StackBlitz 演示</td></tr><tr><td>覆盖范围</td><td>仅核心部分（then / 状态机 / 微任务），不含 catch、finally、静态方法</td></tr></tbody></table><h2 id="二、内容结构" tabindex="-1"><a class="header-anchor" href="#二、内容结构" aria-hidden="true">#</a> 二、内容结构</h2><p>笔记按「规范 → 原理 → 实现 → 总结」四段推进，是一条完整的从理论到落地的链路：</p><ol><li><strong>Promise 规范</strong>：A+ 规定的四个基本约定</li><li><strong>链式调用</strong>：then 的返回值与状态传递规则</li><li><strong>实现 Promise 核心部分</strong>：可直接运行的手写代码</li><li><strong>总结</strong>：四条结论性归纳</li></ol><h2 id="三、逐节解析" tabindex="-1"><a class="header-anchor" href="#三、逐节解析" aria-hidden="true">#</a> 三、逐节解析</h2><h3 id="_1-promise-规范" tabindex="-1"><a class="header-anchor" href="#_1-promise-规范" aria-hidden="true">#</a> 1. Promise 规范</h3><p>把「所有异步场景」抽象为<strong>异步任务</strong>，用**任务对象（Promise）**表示，并给出四条规则：</p><ul><li><strong>两个阶段、三个状态</strong>：未决（pending）→ 已决（fulfilled / rejected）。</li><li><strong>状态不可逆</strong>：任务总是从未决走向已决，从挂起走向完成或失败，「历史不可改写」——一旦 settled 就永久固定。</li><li><strong>两个迁移动作</strong>：<code>挂起 → 完成</code> 称为 <code>resolve</code>；<code>挂起 → 失败</code> 称为 <code>reject</code>。完成可能带<strong>数据</strong>，失败可能带<strong>失败原因</strong>。</li><li><strong>两类后续处理</strong>：完成后的处理叫 <code>onFulfilled</code>，失败后的处理叫 <code>onRejected</code>。</li></ul><blockquote><p>这一节是整篇笔记的「状态机定义」，后面的实现基本是它的直译。</p></blockquote><h3 id="_2-链式调用" tabindex="-1"><a class="header-anchor" href="#_2-链式调用" aria-hidden="true">#</a> 2. 链式调用</h3><p>核心结论两条：</p><ul><li><code>then</code> <strong>一定返回一个新的 Promise</strong>——可理解为「后续处理本身也是一个任务」。</li><li><strong>新任务的状态取决于后续处理</strong>，分五种情况：</li></ul><table><thead><tr><th>后续处理情况</th><th>新任务状态</th></tr></thead><tbody><tr><td>没有对应的后续处理</td><td>与前任务一致，数据为前任务的数据</td></tr><tr><td>有后续处理但还没执行</td><td>新任务挂起（pending）</td></tr><tr><td>处理执行成功（无错）</td><td>fulfilled，数据为<strong>返回值</strong></td></tr><tr><td>处理执行抛错</td><td>rejected，数据为<strong>异常对象</strong></td></tr><tr><td>处理返回的又是一个任务对象</td><td>新任务状态与数据<strong>与该任务对象一致</strong></td></tr></tbody></table><h3 id="_3-实现-promise-核心部分-代码解析" tabindex="-1"><a class="header-anchor" href="#_3-实现-promise-核心部分-代码解析" aria-hidden="true">#</a> 3. 实现 Promise 核心部分（代码解析）</h3><p>代码由四块组成：</p><p><strong>① 常量</strong>：<code>PENDING / FULLFILLED / REJECTED</code>（注意 <code>FULLFILLED</code> 是拼写笔误，应为 <code>FULFILLED</code>，因全局统一所以不影响运行）。</p><p><strong>② <code>runMicroTask(task)</code></strong>：微任务调度，按 Node → 浏览器 → 兜底三级降级：<br><code>process.nextTick</code> → <code>MutationObserver</code> → <code>setTimeout(task, 0)</code>。</p><p><strong>③ <code>isPromise(obj)</code></strong>：鸭子类型判断——是对象且 <code>then</code> 为函数。</p><p><strong>④ <code>class MyPromise</code></strong>，核心方法：</p><table><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>constructor(execute)</code></td><td>初始化 <code>_value / _state / _handlers</code>，try-catch 包裹执行器，同步抛错直接 <code>_reject</code></td></tr><tr><td><code>changeState(data, state)</code></td><td>状态机闸门：非 pending 直接 return；否则写值、写状态，然后触发队列</td></tr><tr><td><code>_resolve / _reject</code></td><td>对 <code>changeState</code> 的语义封装</td></tr><tr><td><code>then(onFulfilled, onRejected)</code></td><td>返回<strong>新 MyPromise</strong>，把两个回调入队，并主动触发一次队列</td></tr><tr><td><code>_pushToQueue(...)</code></td><td>把 <code>{executor, state, resolve, reject}</code> 压入 <code>_handlers</code></td></tr><tr><td><code>_runHandlers()</code></td><td>pending 时不动；否则 while 循环 shift 出队逐个执行</td></tr><tr><td><code>_runOneHandler(...)</code></td><td>包进微任务后执行：状态不匹配→跳过；回调非函数→透传状态与值；回调正常返回→resolve；返回 Promise→<code>result.then(resolve, reject)</code> 接管；抛错→reject</td></tr></tbody></table><p><strong>设计要点</strong>：这是典型的<strong>发布订阅 + 状态机</strong>模型。<code>then</code> 只负责「登记回调」和「尝试执行」，真正的执行时机由 <strong>settled 事件</strong>（<code>changeState</code>）驱动；两者都会调用 <code>_runHandlers()</code>，因此无论「先 then 后 resolve」还是「先 resolve 后 then」都能正确执行。</p><p><strong>演示用例</strong>：<code>p → p2 → p3</code> 的三级链式，配合 <code>setTimeout</code> 校验 1s 后各 Promise 的最终状态，另附一个 StackBlitz 在线 demo（iframe）。</p><h3 id="_4-总结-原文四条" tabindex="-1"><a class="header-anchor" href="#_4-总结-原文四条" aria-hidden="true">#</a> 4. 总结（原文四条）</h3><ol><li><code>then</code> 是把回调加入<strong>微队列</strong>，等状态确定为 settled 才执行。</li><li>多次调用 <code>then</code> 会把回调依次入队，状态确定后<strong>一次性执行完队列</strong>。</li><li><strong>状态确定</strong>或<strong>调用 then</strong> 都会触发队列执行。</li><li><code>then</code> 的回调若不是函数，则状态与前一个 <code>then</code> 保持一致。</li></ol><h2 id="四、链式调用的状态传递实例" tabindex="-1"><a class="header-anchor" href="#四、链式调用的状态传递实例" aria-hidden="true">#</a> 四、链式调用的状态传递实例</h2><blockquote><p>以下用例均已在 Node 环境实际运行，输出为真实结果。</p></blockquote><h3 id="判断流程" tabindex="-1"><a class="header-anchor" href="#判断流程" aria-hidden="true">#</a> 判断流程</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>then 产生新任务 child
├─ 当前分支的回调不是函数 ──────────→ child 透传父任务状态和值
└─ 是函数
   ├─ 还未执行（微任务未到）────────→ child 处于 pending
   └─ 已执行
      ├─ 抛错 ──────────────────────→ child = rejected(异常)
      └─ 正常返回 v
         ├─ v 是 thenable/Promise ───→ child 跟随 v 的状态和值
         └─ 否则 ────────────────────→ child = fulfilled(v)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="实例-1-没有对应后续处理-→-状态与数据完全透传" tabindex="-1"><a class="header-anchor" href="#实例-1-没有对应后续处理-→-状态与数据完全透传" aria-hidden="true">#</a> 实例 1：没有对应后续处理 → 状态与数据完全透传</h3><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// fulfilled 分支无回调</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// A</span>
<span class="token comment">// rejected 分支无回调</span>
Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;E&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token parameter">e</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// E</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：<code>.then()</code> 没有传任何参数，两个分支都「不是函数」，所以原样透传状态与值。</p><h3 id="实例-2-有后续处理但尚未执行-→-新任务挂起" tabindex="-1"><a class="header-anchor" href="#实例-2-有后续处理但尚未执行-→-新任务挂起" aria-hidden="true">#</a> 实例 2：有后续处理但尚未执行 → 新任务挂起</h3><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> p  <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token parameter">r</span> <span class="token operator">=&gt;</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">r</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> p2 <span class="token operator">=</span> p<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> v <span class="token operator">+</span> <span class="token string">&#39;!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>p2<span class="token punctuation">)</span><span class="token punctuation">;</span>              <span class="token comment">// Promise { &lt;pending&gt; }   ← 同步时刻</span>
p2<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// A!                      ← 100ms 后</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：<code>then</code> 返回时回调还没跑，<code>p2</code> 只能挂起；最终状态要等回调执行完才确定。</p><h3 id="实例-3-后续处理执行成功-→-fulfilled-数据为返回值" tabindex="-1"><a class="header-anchor" href="#实例-3-后续处理执行成功-→-fulfilled-数据为返回值" aria-hidden="true">#</a> 实例 3：后续处理执行成功 → fulfilled，数据为返回值</h3><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> v <span class="token operator">+</span> <span class="token string">&#39;B&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// AB</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="实例-4-后续处理执行抛错-→-rejected-数据为异常对象" tabindex="-1"><a class="header-anchor" href="#实例-4-后续处理执行抛错-→-rejected-数据为异常对象" aria-hidden="true">#</a> 实例 4：后续处理执行抛错 → rejected，数据为异常对象</h3><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;boom&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">}</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token parameter">e</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>message<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// boom</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="实例-5-后续处理返回任务对象-→-新任务跟随它" tabindex="-1"><a class="header-anchor" href="#实例-5-后续处理返回任务对象-→-新任务跟随它" aria-hidden="true">#</a> 实例 5：后续处理返回任务对象 → 新任务跟随它</h3><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 5.1 返回已拒绝的 Promise</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;E2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token parameter">e</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                            <span class="token comment">// E2</span>

<span class="token comment">// 5.2 返回挂起的 Promise</span>
<span class="token keyword">const</span> p5 <span class="token operator">=</span> Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">new</span> <span class="token class-name">Promise</span><span class="token punctuation">(</span><span class="token parameter">r</span> <span class="token operator">=&gt;</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token function">r</span><span class="token punctuation">(</span><span class="token string">&#39;late&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">500</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>p5<span class="token punctuation">)</span><span class="token punctuation">;</span>            <span class="token comment">// Promise { &lt;pending&gt; }</span>
p5<span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// late（500ms 后）</span>

<span class="token comment">// 5.3 返回 thenable（非真 Promise 也认）</span>
Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token string">&#39;A&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">res</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token function">res</span><span class="token punctuation">(</span><span class="token string">&#39;thenable&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                             <span class="token comment">// thenable</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：返回 Promise 时不只是「取值」，而是<strong>等它 settled</strong> 再同步状态，这也解释了为什么 <code>p5</code> 会多挂起 500ms。</p><h3 id="两个容易踩的坑" tabindex="-1"><a class="header-anchor" href="#两个容易踩的坑" aria-hidden="true">#</a> 两个容易踩的坑</h3><p><strong>1. onRejected 分支同样适用整条规则</strong></p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code>Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;E3&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token parameter">e</span> <span class="token operator">=&gt;</span> e <span class="token operator">+</span> <span class="token string">&#39;!&#39;</span><span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// E3!   ← 失败被「恢复」为成功</span>

Promise<span class="token punctuation">.</span><span class="token function">reject</span><span class="token punctuation">(</span><span class="token string">&#39;E4&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">v</span> <span class="token operator">=&gt;</span> v<span class="token punctuation">)</span>
  <span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token parameter">e</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// E4    ← 只给了 onFulfilled，等同于无处理</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 返回自身会抛 TypeError（原生行为）</strong></p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> p8 <span class="token operator">=</span> Promise<span class="token punctuation">.</span><span class="token function">resolve</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> p8<span class="token punctuation">)</span><span class="token punctuation">;</span>
p8<span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token parameter">e</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>constructor<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// TypeError</span>
<span class="token comment">// 信息：Chaining cycle detected for promise</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这正是第五节点评第 6 条提到的缺口——笔记里的 <code>MyPromise</code> 没有校验 <code>result === 新 Promise</code>，遇到循环引用会无限等待。</p><h3 id="实例对照表" tabindex="-1"><a class="header-anchor" href="#实例对照表" aria-hidden="true">#</a> 实例对照表</h3><table><thead><tr><th>后续处理</th><th>新任务状态</th><th>数据来源</th></tr></thead><tbody><tr><td>无回调 / 回调非函数</td><td>与父任务一致</td><td>父任务的值</td></tr><tr><td>回调未执行</td><td>pending</td><td>暂无</td></tr><tr><td>回调返回普通值</td><td>fulfilled</td><td>返回值</td></tr><tr><td>回调抛错</td><td>rejected</td><td>异常对象</td></tr><tr><td>回调返回 Promise / thenable</td><td>跟随该对象</td><td>该对象的值</td></tr><tr><td>回调返回自身</td><td>rejected</td><td>TypeError</td></tr></tbody></table><h2 id="五、问题与可改进点-code-review" tabindex="-1"><a class="header-anchor" href="#五、问题与可改进点-code-review" aria-hidden="true">#</a> 五、问题与可改进点（Code Review）</h2><table><thead><tr><th>#</th><th>位置</th><th>问题</th><th>建议</th></tr></thead><tbody><tr><td>1</td><td><code>runMicroTask</code></td><td><code>if(process &amp;&amp; process.nextTick)</code> 在浏览器中 <code>process</code> 未定义会抛 <strong>ReferenceError</strong>，导致直接落到 catch 之外的崩溃</td><td>改为 <code>typeof process !== &#39;undefined&#39; &amp;&amp; process.nextTick</code></td></tr><tr><td>2</td><td><code>runMicroTask</code></td><td><code>else if(MutationObserver)</code> 同理，非浏览器也是裸引用</td><td>改为 <code>typeof MutationObserver !== &#39;undefined&#39;</code></td></tr><tr><td>3</td><td>常量</td><td><code>FULLFILLED</code> 拼写错误（fulfilled），易误导阅读者</td><td>统一改为 <code>FULFILLED</code></td></tr><tr><td>4</td><td><code>runMicroTask</code></td><td>Node 下用 <code>process.nextTick</code>——它<strong>优先级高于 Promise 微任务</strong>，与原生 Promise 的执行时序不一致</td><td>面试讲解时可注明差异，或改用 <code>queueMicrotask</code></td></tr><tr><td>5</td><td><code>then</code> + <code>_runOneHandler</code></td><td>每次 <code>then</code> 把 onFulfilled/onRejected <strong>都入队</strong>，靠 state 匹配过滤、不匹配的直接丢弃，语义略绕且队列无谓翻倍</td><td>可改成按当前状态二选一入队，更贴近 A+ 描述</td></tr><tr><td>6</td><td>循环引用</td><td>未处理「回调返回当前 Promise 自身」的情况，A+ 要求抛 <code>TypeError</code></td><td>增加 <code>result === newPromise</code> 的守卫</td></tr><tr><td>7</td><td>API 覆盖</td><td>只有核心部分，缺 <code>catch</code>、<code>finally</code>、<code>Promise.resolve/reject/all/race/allSettled/any</code></td><td>作为「手写 Promise 全量」需补齐；笔记已注明是「核心部分」，可接受</td></tr><tr><td>8</td><td>演示代码</td><td><code>return Promise.reject(&#39;p2执行错误&#39;)</code> 混用了<strong>原生 Promise</strong> 与 <code>MyPromise</code></td><td>改为 <code>MyPromise.reject(...)</code> 以验证自己的实现</td></tr><tr><td>9</td><td>图片资源</td><td>规范与链式调用小节用 <code>./img/20210618*.png</code> 相对路径引用，在资料库文档中<strong>无法渲染</strong>（图片丢失）</td><td>重新上传图片或改为在线图床链接</td></tr><tr><td>10</td><td>文档结构</td><td>front matter 被写成了正文列表（<code>title:/date:/categories:</code> 以纯文本散落在段落与列表中）</td><td>若要保持 front matter 语义，应放在文档顶部并由编辑器识别</td></tr></tbody></table><h2 id="六、知识点小结-可迁移结论" tabindex="-1"><a class="header-anchor" href="#六、知识点小结-可迁移结论" aria-hidden="true">#</a> 六、知识点小结（可迁移结论）</h2><ul><li><strong>三状态两阶段 + 状态不可逆</strong>，是 Promise 一切行为的地基。</li><li><strong>回调队列（发布订阅）</strong> 解决了「then 早于 resolve 调用」的时序问题。</li><li><strong>微任务调度</strong> 保证回调异步执行，不阻塞同步代码。</li><li><strong>then 返回新 Promise</strong> 是链式调用的关键，也是「后续处理即一个新任务」的落地方式。</li></ul><h2 id="七、原文位置速查" tabindex="-1"><a class="header-anchor" href="#七、原文位置速查" aria-hidden="true">#</a> 七、原文位置速查</h2><table><thead><tr><th>小节</th><th>内容类型</th></tr></thead><tbody><tr><td>Promise规范</td><td>2 个有序列表 + 4 张说明图（图片缺失）</td></tr><tr><td>链式调用</td><td>1 张状态图（缺失）+ 2 条有序列表</td></tr><tr><td>实现Promise核心部分</td><td>1 段完整 JS 代码 + 1 个 StackBlitz iframe</td></tr><tr><td>总结</td><td>4 段结论性文字</td></tr></tbody></table>`,57),p=[o];function c(i,l){return s(),a("div",null,p)}const r=n(e,[["render",c],["__file","promise-notes-analysis.html.vue"]]);export{r as default};
